/*
 * Form explorer: a form's Composition model as clinical views - an overview, a data table,
 * a mind map and a form preview - laid out like the clinical views of the WEST-A guide.
 *
 * The data comes from form-explorer/form-*.json, generated by
 * .github/scripts/build_form_explorer.py from the mapping pages, the Composition profile
 * and the terminology it binds to. Lives in input/images/ so Jekyll leaves it alone.
 */
(() => {
  'use strict';

  const root = document.getElementById('fx');
  if (!root) return;
  root.classList.add('fx');
  const css = document.createElement('link');
  css.rel = 'stylesheet';
  css.href = 'form-explorer.css';
  document.head.appendChild(css);
  const lm = /\/(en|ru|uz)\/[^/]*$/.exec(location.pathname);
  let LANG = (lm && lm[1]) || (document.documentElement.lang || 'en').slice(0, 2);
  if (!/^(en|ru|uz)$/.test(LANG)) LANG = 'en';

  const STRINGS = {
    en: {
      loading: 'Loading the form model...', mappingLink: 'Field mapping', allForms: 'All forms', failed: 'Could not load the form model: ', pick: 'Form', labels: 'Field labels',
      views: { overview: 'Overview', data: 'Data', mindmap: 'Mind map', form: 'Form preview' },
      composition: 'Composition', expandAll: 'Expand all', collapseAll: 'Collapse all', zoomIn: 'Zoom in', zoomOut: 'Zoom out',
      selectHint: 'Select a data element to see what it holds.',
      showPaths: 'Show FHIR paths', fillExample: 'Fill with example data', clearExample: 'Clear example data',
      colElement: 'Data element', colDesc: 'Description', colValues: 'Allowed values',
      dataLegend: 'Grey bars are sections, items with a dashed outline link to another record.',
      formLegend: 'mandatory · [min..max] how many times an element may occur',
      mand: 'Mandatory', opt: 'Optional', rep: 'Repeats', grouping: 'Grouping for readability', docSection: 'Document header, not a section',
      leads: { required: 'Must be from', extensible: 'From this list where it has a fitting code', preferred: 'Preferably from', example: 'For example from' },
      refersTo: 'Refers to: ', exampleV: 'Example: ', itemCode: 'Code: ', sectionCode: 'Section code: ', entries: 'Entries: ',
      elements: n => n + (n === 1 ? ' element: ' : ' elements: '), resource: 'Resource: ', unit: 'Unit: ',
      codes: 'codes', more: n => '+' + n + ' more', exampleHit: 'example value',
      notExpanded: 'Also includes codes from ', tooMany: ' codes, too many to list here. Open the value set to browse them.',
      noList: 'Coded, with no fixed answer list on this form.', notSent: 'Not sent to the platform', derivedNote: 'Derived, not entered',
      concept: 'Form', otherTitles: 'Also titled', docType: 'Document type', header: 'Document header', sections: 'Sections', source: 'Source',
      counts: ['data elements', 'mandatory', 'sections'], fhirResource: 'FHIR resource', profile: 'Composition profile',
      mapping: 'Field mapping page', example: 'Example document', languages: 'Field label languages', dataTypes: 'Data types',
      root: 'Form ',
      foot: 'Built from the form\'s mapping pages (en, ru, uz), its Composition profile and the code systems and value sets those bind to. Section codes, cardinality and entry types come from the profile, field data types and bindings from the profile of each field\'s resource. Example values are the ones on the mapping page.',
      types: { quantity: 'Quantity with unit', text: 'Text', coded: 'Coded text (chosen from a list)', date: 'Date', datetime: 'Date and time', boolean: 'Yes / no',
        identifier: 'Identifier', reference: 'Link to another record', count: 'Count', period: 'Period (from - to)', attachment: 'Attachment',
        derived: 'Derived, not entered', none: 'Not sent', group: 'Group of elements' }
    },
    ru: {
      loading: 'Загрузка модели формы...', mappingLink: 'Сопоставление полей', allForms: 'Все формы', failed: 'Не удалось загрузить модель формы: ', pick: 'Форма', labels: 'Названия полей',
      views: { overview: 'Обзор', data: 'Данные', mindmap: 'Карта', form: 'Просмотр формы' },
      composition: 'Composition', expandAll: 'Развернуть все', collapseAll: 'Свернуть все', zoomIn: 'Увеличить', zoomOut: 'Уменьшить',
      selectHint: 'Выберите элемент данных, чтобы увидеть, что он содержит.',
      showPaths: 'Показать пути FHIR', fillExample: 'Заполнить данными из примера', clearExample: 'Очистить данные примера',
      colElement: 'Элемент данных', colDesc: 'Описание', colValues: 'Допустимые значения',
      dataLegend: 'Серые полосы - разделы, элементы с пунктирной рамкой ссылаются на другую запись.',
      formLegend: 'обязательно · [мин..макс] сколько раз может встречаться элемент',
      mand: 'Обязательно', opt: 'Необязательно', rep: 'Повторяется', grouping: 'Группировка для удобства', docSection: 'Заголовок документа, не раздел',
      leads: { required: 'Только из', extensible: 'Из этого списка, если в нём есть подходящий код', preferred: 'Предпочтительно из', example: 'Например, из' },
      refersTo: 'Ссылается на: ', exampleV: 'Пример: ', itemCode: 'Код: ', sectionCode: 'Код раздела: ', entries: 'Записи: ',
      elements: n => 'Элементов: ' + n + ' - ', resource: 'Ресурс: ', unit: 'Единица: ',
      codes: 'кодов', more: n => 'ещё ' + n, exampleHit: 'значение из примера',
      notExpanded: 'Также включает коды из ', tooMany: ' кодов, слишком много для списка. Откройте набор значений, чтобы просмотреть их.',
      noList: 'Кодируемое поле без фиксированного списка ответов в этой форме.', notSent: 'Не передаётся на платформу', derivedNote: 'Вычисляется, не вводится',
      concept: 'Форма', otherTitles: 'Другие названия', docType: 'Тип документа', header: 'Заголовок документа', sections: 'Разделы', source: 'Источник',
      counts: ['элементов данных', 'обязательных', 'разделов'], fhirResource: 'Ресурс FHIR', profile: 'Профиль Composition',
      mapping: 'Страница сопоставления', example: 'Пример документа', languages: 'Языки названий полей', dataTypes: 'Типы данных',
      root: 'Форма ',
      foot: 'Построено по страницам сопоставления формы (en, ru, uz), её профилю Composition и связанным с ними системам кодов и наборам значений. Коды разделов, кратность и типы записей взяты из профиля, типы данных и привязки полей - из профиля ресурса каждого поля. Примеры значений взяты со страницы сопоставления.',
      types: { quantity: 'Количество с единицей', text: 'Текст', coded: 'Код (выбор из списка)', date: 'Дата', datetime: 'Дата и время', boolean: 'Да / нет',
        identifier: 'Идентификатор', reference: 'Ссылка на другую запись', count: 'Число', period: 'Период (с - по)', attachment: 'Вложение',
        derived: 'Вычисляется, не вводится', none: 'Не передаётся', group: 'Группа элементов' }
    },
    uz: {
      loading: 'Shakl modeli yuklanmoqda...', mappingLink: 'Maydonlarni moslashtirish', allForms: 'Barcha shakllar', failed: 'Shakl modelini yuklab bo\'lmadi: ', pick: 'Shakl', labels: 'Maydon nomlari',
      views: { overview: 'Umumiy ko\'rinish', data: 'Ma\'lumotlar', mindmap: 'Xarita', form: 'Shakl ko\'rinishi' },
      composition: 'Composition', expandAll: 'Hammasini ochish', collapseAll: 'Hammasini yopish', zoomIn: 'Kattalashtirish', zoomOut: 'Kichraytirish',
      selectHint: 'Nimani saqlashini ko\'rish uchun ma\'lumot elementini tanlang.',
      showPaths: 'FHIR yo\'llarini ko\'rsatish', fillExample: 'Namuna ma\'lumotlari bilan to\'ldirish', clearExample: 'Namuna ma\'lumotlarini tozalash',
      colElement: 'Ma\'lumot elementi', colDesc: 'Tavsif', colValues: 'Ruxsat etilgan qiymatlar',
      dataLegend: 'Kulrang qatorlar - bo\'limlar, punktir ramkali elementlar boshqa yozuvga havola qiladi.',
      formLegend: 'majburiy · [min..maks] element necha marta uchrashi mumkin',
      mand: 'Majburiy', opt: 'Ixtiyoriy', rep: 'Takrorlanadi', grouping: 'Qulaylik uchun guruhlash', docSection: 'Hujjat sarlavhasi, bo\'lim emas',
      leads: { required: 'Faqat shu ro\'yxatdan', extensible: 'Mos kod bo\'lsa, shu ro\'yxatdan', preferred: 'Imkon qadar shu ro\'yxatdan', example: 'Masalan, shu ro\'yxatdan' },
      refersTo: 'Havola: ', exampleV: 'Namuna: ', itemCode: 'Kod: ', sectionCode: 'Bo\'lim kodi: ', entries: 'Yozuvlar: ',
      elements: n => n + ' ta element: ', resource: 'Resurs: ', unit: 'Birlik: ',
      codes: 'kod', more: n => 'yana ' + n, exampleHit: 'namuna qiymati',
      notExpanded: 'Shuningdek, quyidagi kodlarni o\'z ichiga oladi: ', tooMany: ' kod, ro\'yxat uchun juda ko\'p. Ularni ko\'rish uchun qiymatlar to\'plamini oching.',
      noList: 'Kodlangan maydon, bu shaklda belgilangan javoblar ro\'yxati yo\'q.', notSent: 'Platformaga yuborilmaydi', derivedNote: 'Hisoblanadi, kiritilmaydi',
      concept: 'Shakl', otherTitles: 'Boshqa nomlari', docType: 'Hujjat turi', header: 'Hujjat sarlavhasi', sections: 'Bo\'limlar', source: 'Manba',
      counts: ['ma\'lumot elementi', 'majburiy', 'bo\'lim'], fhirResource: 'FHIR resursi', profile: 'Composition profili',
      mapping: 'Moslashtirish sahifasi', example: 'Hujjat namunasi', languages: 'Maydon nomlari tillari', dataTypes: 'Ma\'lumot turlari',
      root: '', rootSuffix: '-shakl',
      foot: 'Shaklning moslashtirish sahifalari (en, ru, uz), uning Composition profili va ular bog\'langan kod tizimlari hamda qiymatlar to\'plamlari asosida tuzilgan. Bo\'lim kodlari, kardinallik va yozuv turlari profildan, maydonlarning ma\'lumot turlari va bog\'lanishlari esa har bir maydon resursining profilidan olingan. Namuna qiymatlari moslashtirish sahifasidan olingan.',
      types: { quantity: 'Birlikli miqdor', text: 'Matn', coded: 'Kod (ro\'yxatdan tanlanadi)', date: 'Sana', datetime: 'Sana va vaqt', boolean: 'Ha / yo\'q',
        identifier: 'Identifikator', reference: 'Boshqa yozuvga havola', count: 'Son', period: 'Davr (dan - gacha)', attachment: 'Ilova',
        derived: 'Hisoblanadi, kiritilmaydi', none: 'Yuborilmaydi', group: 'Elementlar guruhi' }
    }
  };
  const S = STRINGS[LANG];
  const GLYPH = { text: 'T', coded: '≡', quantity: 'Q', count: '#', date: 'D', datetime: 'DT', period: '↔', identifier: 'ID',
    boolean: '✓', reference: '→', attachment: 'A', derived: '=', none: '–', group: '▤' };
  const TCOLOR = { quantity: 'qty', count: 'qty', date: 'date', datetime: 'date', period: 'date', identifier: 'id', attachment: 'id',
    derived: 'id', none: 'id', boolean: 'bool', reference: 'link', text: 'text', coded: 'coded' };
  const VIEWS = ['overview', 'data', 'mindmap', 'form'];

  let M = null, FIELDS = [], TREE = null;
  const state = { form: null, labels: LANG, view: 'overview', paths: false, example: false };
  try {
    const saved = JSON.parse(localStorage.getItem('fx-explorer') || '{}');
    if (['en', 'uz', 'ru'].includes(saved.labels)) state.labels = saved.labels;
    if (typeof saved.paths === 'boolean') state.paths = saved.paths;
  } catch (e) { /* storage unavailable */ }
  function save() { try { localStorage.setItem('fx-explorer', JSON.stringify({ labels: state.labels, paths: state.paths })); } catch (e) { /* ignore */ } }

  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const url = u => /^(https?:\/\/|[\w.-]+\.html)/.test(u || '') ? esc(u) : '#';
  const ext = u => /^https?:/.test(u) ? ' target="_blank" rel="noopener"' : '';
  const $ = sel => root.querySelector(sel);
  const L = o => (o && (o[LANG] || o.en || o.uz || o.ru)) || '';
  const label = f => f.label[state.labels] || f.label[LANG] || f.label.uz || f.label.ru;
  const altLabel = f => [...new Set(['en', 'uz', 'ru'].map(k => f.label[k]).filter(x => x && x !== label(f)))].join(' · ');
  const concept = c => c[LANG] || c.en || c.uz || c.ru || c.code;
  const icon = t => `<span class="ti ${TCOLOR[t] || t}" title="${esc(S.types[t])}" aria-label="${esc(S.types[t])}">${GLYPH[t]}</span>`;
  const rootLabel = () => LANG === 'uz' ? M.form + S.rootSuffix : S.root + M.form;
  const list = f => f.valueList && M.valueLists[f.valueList];
  const humanize = s => { const t = s.replace(/([a-z0-9])([A-Z])/g, '$1 $2').toLowerCase(); return t.charAt(0).toUpperCase() + t.slice(1); };
  function subOf(s, f) { return f.subsection ? s.subsections.find(x => x.slice === f.subsection) || null : null; }
  function occ(card) {
    if (!card) return { mand: false, rep: false };
    const [min, max] = card.split('..');
    return { mand: min !== '0', rep: max === '*' || +max > 1 };
  }
  function tags(n) {
    if (!n.card) return `<span class="chip opt">${esc(n.sec && !n.sec.slice ? S.docSection : S.grouping)}</span>`;
    const o = occ(n.card);
    let h = o.mand ? `<span class="chip mand">${esc(S.mand)}</span>` : `<span class="chip opt">${esc(S.opt)}</span>`;
    if (o.rep) h += `<span class="chip rep">${esc(S.rep)}</span>`;
    return h + ` <span class="car">[${esc(n.card)}]</span>`;
  }
  function walk(n, fn, depth = 0, parent = null) { fn(n, depth, parent); (n.children || []).forEach(c => walk(c, fn, depth + 1, n)); }
  function codeHtml(c) {
    if (!c) return '';
    let code = esc(c.code);
    if (c.system === 'LOINC') code = `<a class="mono" href="https://loinc.org/${encodeURIComponent(c.code)}"${ext('https:')}>${code}</a>`;
    else if (c.link) code = `<a class="mono" href="${url(c.link)}"${ext(c.link)}>${code}</a>`;
    else code = `<span class="mono">${code}</span>`;
    return `${esc(c.system)} ${code}${c.display ? ` <span class="muted">${esc(c.display)}</span>` : ''}`;
  }
  const count = vl => vl.total + (vl.incomplete && vl.incomplete.length ? '+' : '');
  const vsLink = b => b.link ? `<a href="${url(b.link)}"${ext(b.link)}>${esc(b.title)}</a>` : esc(b.title);
  function bindingLine(f) {
    const vl = list(f), b = f.binding;
    if (b) return `${esc(S.leads[b.strength] || b.strength)}: ${vsLink(b)}${vl ? ` <span class="muted">(${count(vl)} ${esc(S.codes)})</span>` : ''}`;
    if (vl) return `${vl.link ? `<a href="${url(vl.link)}"${ext(vl.link)}>${esc(vl.title)}</a>` : esc(vl.title)} <span class="muted">(${count(vl)} ${esc(S.codes)})</span>`;
    return '';
  }

  function exampleConcept(f) {
    const vl = list(f);
    if (!vl || !vl.concepts.length || !f.example) return null;
    const ex = f.example.toLowerCase().replace(/^"|"$/g, '');
    let inParens = [];
    ex.replace(/\(([^()]*)\)/g, (_, g) => { inParens = inParens.concat(g.split(',').map(s => s.trim())); });
    let hit = vl.concepts.find(c => { const code = c.code.toLowerCase(); return ex === code || ex.indexOf(code + ' ') === 0 || inParens.includes(code); });
    if (hit) return hit;
    let best = 0;
    vl.concepts.some(c => ['en', 'ru', 'uz'].some(k => {
      const d = (c[k] || '').toLowerCase();
      if (!d) return false;
      if (ex === d) { hit = c; best = Infinity; return true; }
      if ((ex.indexOf(d) === 0 || d.indexOf(ex) === 0) && Math.min(d.length, ex.length) > best) { hit = c; best = Math.min(d.length, ex.length); }
      return false;
    }));
    return hit || null;
  }

  function buildTree() {
    const r = { uid: 'root', label: rootLabel(), type: 'group', children: [] };
    M.sections.forEach((s, i) => {
      const sec = { uid: 's' + i, label: L(s.title), type: 'group', card: s.slice ? s.card : null, sec: s, children: [] };
      const subs = {};
      s.fields.forEach(f => {
        const leaf = { uid: f.id, label: label(f), type: f.type, card: f.card, f };
        const sub = subOf(s, f);
        if (!sub) { sec.children.push(leaf); return; }
        if (!subs[sub.slice]) {
          subs[sub.slice] = { uid: 's' + i + '.' + sub.slice, label: humanize(sub.slice), type: 'group', card: sub.card, sub, children: [] };
          sec.children.push(subs[sub.slice]);
        }
        subs[sub.slice].children.push(leaf);
      });
      r.children.push(sec);
    });
    return r;
  }

  /* ---------------------------------------------------------------- shell */

  function shell(index) {
    root.innerHTML =
      `<div class="models"><span class="lbls">${esc(S.labels)} <span class="seg" role="group" aria-label="${esc(S.labels)}">` +
      `<button type="button" data-l="en">English</button><button type="button" data-l="uz">O'zbek</button><button type="button" data-l="ru">Русский</button></span></span>` +
      `<label class="pick on"><span>${esc(S.pick)}</span><select id="fx-form">` +
      index.map(x => `<option value="${esc(x.form)}">${esc(L(x.title))}</option>`).join('') + '</select></label></div>' +
      '<div class="sheet"><div class="titlebar" id="fx-title"></div>' +
      `<nav class="views" role="tablist" aria-label="${esc(S.pick)}">` +
      VIEWS.map(v => `<button type="button" role="tab" id="fx-v-${v}" data-view="${v}">${esc(S.views[v])}</button>`).join('') + '</nav>' +
      '<div class="pane" id="fx-pane" role="tabpanel"></div></div>';
    $('#fx-form').addEventListener('change', e => go(e.target.value));
    $('.lbls').addEventListener('click', e => {
      const b = e.target.closest('button[data-l]');
      if (!b || !M) return;
      state.labels = b.dataset.l;
      save();
      TREE = buildTree();
      render();
    });
    const views = $('.views');
    views.addEventListener('click', e => { const b = e.target.closest('button[data-view]'); if (b) { state.view = b.dataset.view; render(); } });
    views.addEventListener('keydown', e => {
      if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
      const i = VIEWS.indexOf(state.view);
      state.view = VIEWS[(i + (e.key === 'ArrowRight' ? 1 : VIEWS.length - 1)) % VIEWS.length];
      render();
      $('#fx-v-' + state.view).focus();
    });
  }

  function render() {
    if (!M) return;
    $('#fx-title').innerHTML =
      `<h2><span class="ti group fno">${esc(M.form)}</span>${esc(L(M.title))}</h2>` +
      `<span class="meta">${esc(S.composition)} · <span class="mono">${esc(M.profile.name)}</span></span>` +
      `<span class="tlinks"><a href="${url(M.profile.mapping)}">${esc(S.mappingLink)}</a><a href="forms-overview.html">${esc(S.allForms)}</a></span>`;
    VIEWS.forEach(v => {
      const b = $('#fx-v-' + v), on = v === state.view;
      b.setAttribute('aria-selected', String(on));
      b.tabIndex = on ? 0 : -1;
    });
    root.querySelectorAll('.lbls button').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.l === state.labels)));
    const pane = $('#fx-pane');
    pane.setAttribute('aria-labelledby', 'fx-v-' + state.view);
    ({ overview: renderOverview, data: renderData, mindmap: renderMindmap, form: renderForm })[state.view](pane);
    writeUrl();
  }

  /* ---------------------------------------------------------------- overview */

  function renderOverview(pane) {
    let total = 0, mand = 0;
    // an element is mandatory only when every group above it is too
    walk(TREE, (n, d, p) => { n.req = n === TREE || (p.req && (!n.card || occ(n.card).mand)); if (!n.children) { total++; if (n.req && n.card) mand++; } });
    const secs = M.sections.filter(s => s.slice).length;
    const type = M.header.find(h => h.el === 'type');
    const others = ['en', 'ru', 'uz'].filter(k => k !== LANG && M.title[k] && M.title[k] !== L(M.title)).map(k => M.title[k]);
    const used = {};
    FIELDS.forEach(f => { used[f.type] = true; });
    pane.innerHTML = `<div class="ov"><dl>
      <dt>${esc(S.concept)}</dt><dd><p><b>${esc(L(M.title))}</b></p></dd>
      ${others.length ? `<dt>${esc(S.otherTitles)}</dt><dd>${others.map(t => `<p>${esc(t)}</p>`).join('')}</dd>` : ''}
      ${type ? `<dt>${esc(S.docType)}</dt><dd><p>${esc(type.note)}</p></dd>` : ''}
      <dt>${esc(S.sections)}</dt><dd><ul class="secs">${M.sections.map((s, i) => `<li><button type="button" class="lnk" data-sec="${i}">${esc(L(s.title))}</button> ${tags(TREE.children[i])}</li>`).join('')}</ul></dd>
      <dt>${esc(S.header)}</dt><dd><ul class="hdr">${M.header.map(h => `<li>${icon(h.type)}<span class="mono">${esc(h.el)}</span> <span class="car">[${esc(h.card)}]</span>${h.note ? ` <span class="muted">${esc(h.note)}</span>` : ''}</li>`).join('')}</ul></dd>
      <dt>${esc(S.source)}</dt><dd><p>${esc(S.foot)}</p></dd>
    </dl>
    <aside class="side">
      <div class="counts"><div><b>${total}</b><span>${esc(S.counts[0])}</span></div><div><b>${mand}</b><span>${esc(S.counts[1])}</span></div><div><b>${secs}</b><span>${esc(S.counts[2])}</span></div></div>
      <div><h3>${esc(S.fhirResource)}</h3><div class="v">Composition</div></div>
      <div><h3>${esc(S.profile)}</h3><div class="v"><a href="${url(M.profile.link)}">${esc(M.profile.title || M.profile.name)}</a></div></div>
      <div><h3>${esc(S.mapping)}</h3><div class="v"><a href="${url(M.profile.mapping)}">${esc(M.profile.mapping)}</a></div></div>
      <div><h3>${esc(S.example)}</h3><div class="v"><a href="${url(M.profile.example)}">${esc(M.profile.example.replace(/\.html$/, ''))}</a></div></div>
      <div><h3>${esc(S.languages)}</h3><div class="v">English, O'zbek, Русский</div></div>
      <div><h3>${esc(S.dataTypes)}</h3><div class="legend">${Object.keys(GLYPH).filter(t => used[t] || t === 'group').map(t => `<div>${icon(t)} ${esc(S.types[t])}</div>`).join('')}</div></div>
    </aside></div>`;
    pane.querySelector('.secs').addEventListener('click', e => {
      const b = e.target.closest('[data-sec]');
      if (!b) return;
      const uid = 's' + b.dataset.sec;
      formClosed[uid] = false;
      state.view = 'form';
      render();
      const fs = pane.querySelector(`[data-fs="${uid}"]`);
      if (fs) { fs.scrollIntoView({ block: 'start' }); fs.querySelector('.fh').focus(); }
    });
  }

  /* ---------------------------------------------------------------- data table */

  function valuesHtml(f, cap) {
    const vl = list(f), hit = exampleConcept(f);
    let h = '';
    if (vl && vl.concepts.length) {
      const li = c => `<li${c === hit ? ` class="hit" title="${esc(S.exampleHit)}"` : ''}>${esc(concept(c))}</li>`;
      const head = vl.concepts.slice(0, cap), rest = vl.concepts.slice(cap);
      h += `<ul>${head.map(li).join('')}</ul>`;
      if (rest.length) h += `<details class="more"><summary>${esc(S.more(rest.length))}</summary><ul>${rest.map(li).join('')}</ul></details>`;
    }
    const bl = bindingLine(f);
    if (bl) h += `<div>${bl}</div>`;
    if (vl && vl.incomplete && vl.incomplete.length) h += `<div class="muted">${esc(S.notExpanded + vl.incomplete.join(', '))}</div>`;
    if (f.type === 'quantity') { const u = f.example.split(' ').slice(1).join(' '); if (u && /^-?\d/.test(f.example)) h += `<div>${esc(S.unit + u)}</div>`; }
    if (f.type === 'reference' && f.targets) h += `<div>${esc(S.refersTo + f.targets.join(', '))}</div>`;
    if (f.type === 'none') h += `<div class="muted">${esc(S.notSent)}</div>`;
    if (f.type === 'derived') h += `<div class="muted">${esc(S.derivedNote)}</div>`;
    if (f.example) h += `<div class="ex">${esc(S.exampleV)}<b>${esc(f.example)}</b></div>`;
    return h;
  }
  function descHtml(f) {
    let h = '';
    if (altLabel(f)) h += `<div class="alt">${esc(altLabel(f))}</div>`;
    if (f.code) h += `<div>${esc(S.itemCode)}${codeHtml(f.code)}</div>`;
    if (f.note && !f.code) h += `<div>${esc(f.note)}</div>`;
    return h;
  }
  function groupDesc(n) {
    const bits = [];
    const code = (n.sec || n.sub || {}).code;
    if (code && code.code) bits.push(esc(S.sectionCode) + codeHtml(code));
    if (n.sec && n.sec.entries && n.sec.entries.length) bits.push(esc(S.entries) + n.sec.entries.map(esc).join(', '));
    if (n.sec && L(n.sec.intro)) bits.push(esc(L(n.sec.intro)));
    return bits;
  }
  function renderData(pane) {
    let rows = '';
    walk(TREE, (n, d) => {
      if (n === TREE) return;
      const path = state.paths && n.f ? `<div class="path">${esc(n.f.path)}</div>` : state.paths && n.sec && n.sec.slice ? `<div class="path">Composition.section:${esc(n.sec.slice)}</div>` : '';
      if (n.children) {
        rows += `<tr class="grp d${d > 1 ? 1 : 0}"><td colspan="3" style="padding-left:${12 + (d - 1) * 22}px">
          <div class="el"><div class="nm">${icon('group')}<span><span class="gname">${esc(n.label)}</span> <span class="tg">${tags(n)}</span></span></div>
          ${groupDesc(n).map(b => `<div class="typ">${b}</div>`).join('')}${path}</div></td></tr>`;
        return;
      }
      rows += `<tr><td style="padding-left:${12 + (d - 1) * 22}px"><div class="el">
          <div class="nm">${icon(n.type)}<span>${esc(n.label)}</span></div>
          <div class="typ">${esc(S.types[n.type])}</div>
          <div class="tags">${tags(n)}</div>${path}</div></td>
        <td><div class="desc">${descHtml(n.f)}</div></td>
        <td><div class="cons">${valuesHtml(n.f, 8)}</div></td></tr>`;
    });
    pane.innerHTML = `<div class="toolbar">
        <label><input type="checkbox" id="fx-paths" ${state.paths ? 'checked' : ''}> ${esc(S.showPaths)}</label>
        <span class="sp"></span><span>${esc(S.dataLegend)}</span></div>
      <div class="tbl-wrap"><table class="data"><thead><tr><th style="width:32%">${esc(S.colElement)}</th><th>${esc(S.colDesc)}</th><th style="width:30%">${esc(S.colValues)}</th></tr></thead><tbody>${rows}</tbody></table></div>`;
    pane.querySelector('#fx-paths').onchange = e => { state.paths = e.target.checked; save(); renderData(pane); };
  }

  /* ---------------------------------------------------------------- mind map */

  let mmCollapsed = {}, mmZoom = null, mmSel = null;
  const measure = document.createElement('canvas').getContext('2d');
  const textW = (s, font) => { measure.font = font; return measure.measureText(s).width; };
  const findNode = uid => { let r = null; walk(TREE, n => { if (n.uid === uid) r = n; }); return r; };

  function renderMindmap(pane) {
    pane.innerHTML = `<div class="mm-tools">
        <button type="button" class="tbtn" id="mm-out" aria-label="${esc(S.zoomOut)}">−</button>
        <button type="button" class="tbtn" id="mm-in" aria-label="${esc(S.zoomIn)}">+</button>
        <button type="button" class="tbtn" id="mm-exp">${esc(S.expandAll)}</button>
        <button type="button" class="tbtn" id="mm-col">${esc(S.collapseAll)}</button></div>
      <div class="mm-box" id="mm-box"></div>
      <div class="mm-detail" id="mm-detail" aria-live="polite"><span class="muted">${esc(S.selectHint)}</span></div>`;
    const box = pane.querySelector('#mm-box'), detail = pane.querySelector('#mm-detail');
    const draw = () => drawMindmap(box, detail);
    const zoomTo = z => { mmZoom = Math.max(0.4, Math.min(1.8, z)); draw(); };
    pane.querySelector('#mm-in').onclick = () => zoomTo(mmZoom + 0.15);
    pane.querySelector('#mm-out').onclick = () => zoomTo(mmZoom - 0.15);
    pane.querySelector('#mm-exp').onclick = () => { mmCollapsed = {}; draw(); };
    pane.querySelector('#mm-col').onclick = () => { TREE.children.forEach(c => { if (c.children) mmCollapsed[c.uid] = true; }); draw(); };
    const first = mmZoom == null;
    if (first) mmZoom = 1;
    const size = draw();
    if (first) zoomTo(Math.min(1, (box.clientWidth - 4) / size.W, (Math.min(720, innerHeight * 0.75) - 4) / size.H));
    requestAnimationFrame(() => { box.scrollLeft = (box.scrollWidth - box.clientWidth) / 2; box.scrollTop = (box.scrollHeight - box.clientHeight) / 2; });
    if (mmSel) showDetail(detail, findNode(mmSel));
  }

  function drawMindmap(box, detail) {
    const ROW = 34, H = 26, GAPX = 46, PAD = 30;
    const fam = getComputedStyle(root).fontFamily || 'sans-serif';
    const FONT = '500 13px ' + fam, FONTB = '600 13px ' + fam;
    const vis = n => n.children && n.children.length && !mmCollapsed[n.uid] ? n.children : [];
    const leaves = n => { const c = vis(n); return c.length ? c.reduce((a, x) => a + leaves(x), 0) : 1; };
    const nodeW = n => Math.ceil(textW(n.label, n.type === 'group' ? FONTB : FONT)) + 24 + (n.type === 'group' ? 0 : 26);

    const tops = TREE.children, total = tops.reduce((a, c) => a + leaves(c), 0);
    const right = [], left = [];
    let acc = 0;
    tops.forEach(c => { const k = leaves(c); if (acc + k / 2 <= total / 2) { right.push(c); acc += k; } else left.push(c); });

    function layoutSide(list) {
      const colW = [];
      const depthW = (n, d) => { colW[d] = Math.max(colW[d] || 0, nodeW(n)); vis(n).forEach(c => depthW(c, d + 1)); };
      list.forEach(n => depthW(n, 0));
      let row = 0;
      const items = [];
      const place = (n, d, parent) => {
        const c = vis(n);
        let y;
        if (c.length) { const ys = c.map(x => place(x, d + 1, n)); y = (ys[0] + ys[ys.length - 1]) / 2; } else { y = row * ROW; row++; }
        items.push({ n, d, y, parent });
        return y;
      };
      list.forEach(n => place(n, 0, TREE));
      const off = (row - 1) * ROW / 2, colX = [];
      let x = 0;
      colW.forEach((w, d) => { colX[d] = x; x += w + GAPX; });
      items.forEach(it => { it.y -= off; it.w = nodeW(it.n); it.x = colX[it.d]; });
      return { items, width: x - GAPX, rows: row };
    }
    const rootW = Math.ceil(textW(TREE.label, '600 17px ' + fam)) + 48, rootH = 44;
    const R = layoutSide(right), Lf = layoutSide(left), gap0 = 70;
    const halfH = Math.max(R.rows, Lf.rows, 2) * ROW / 2 + PAD;
    const leftExt = Lf.items.length ? Lf.width + gap0 : 0, rightExt = R.items.length ? R.width + gap0 : 0;
    const cx = PAD + leftExt + rootW / 2, cy = halfH;
    const W = cx + rootW / 2 + rightExt + PAD, Ht = halfH * 2;

    const pos = new Map();
    pos.set(TREE, { x: cx - rootW / 2, y: cy - rootH / 2, w: rootW, h: rootH, cx, cy });
    R.items.forEach(it => pos.set(it.n, { x: cx + rootW / 2 + gap0 + it.x, y: cy + it.y - H / 2, w: it.w, h: H, cy: cy + it.y, dir: 1 }));
    Lf.items.forEach(it => pos.set(it.n, { x: cx - rootW / 2 - gap0 - it.x - it.w, y: cy + it.y - H / 2, w: it.w, h: H, cy: cy + it.y, dir: -1 }));

    let edges = '', nodes = '';
    const all = [...R.items, ...Lf.items];
    all.forEach(it => {
      const p = pos.get(it.parent), c = pos.get(it.n), dir = c.dir;
      let sx = dir > 0 ? p.x + p.w : p.x;
      if (it.parent !== TREE) sx += dir * 14;
      const ex = dir > 0 ? c.x : c.x + c.w, mx = (sx + ex) / 2;
      edges += `<path class="mm-edge" d="M${sx},${p.cy} C${mx},${p.cy} ${mx},${c.cy} ${ex},${c.cy}"/>`;
    });
    const nodeSvg = (n, p) => {
      const sel = mmSel === n.uid ? ' sel' : '';
      if (n === TREE) return `<g class="mm-node root"><rect class="box" x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}" rx="${p.h / 2}"/><text x="${p.cx}" y="${p.cy + 6}" text-anchor="middle">${esc(n.label)}</text></g>`;
      const cls = n.type === 'group' ? 'group' : n.type === 'reference' ? 'link' : 'leaf';
      const opt = n.type === 'group' && n.card && !occ(n.card).mand ? ' opt' : '';
      let g = `<g class="mm-node ${cls}${opt}${sel}" data-uid="${esc(n.uid)}" tabindex="0" role="button" aria-label="${esc(n.label)}"><title>${esc(n.label)} - ${esc(S.types[n.type])}${n.card ? ', ' + esc(n.card) : ''}</title>`;
      g += `<rect class="box" x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}" rx="4"/>`;
      let tx = p.x + 12;
      if (n.type !== 'group') {
        g += `<g class="ico ${TCOLOR[n.type]}"><rect x="${p.x + 8}" y="${p.y + 5}" width="20" height="16" rx="3"${n.type === 'reference' ? ' stroke-dasharray="3 2"' : ''}/><text x="${p.x + 18}" y="${p.y + 17}" text-anchor="middle">${esc(GLYPH[n.type])}</text></g>`;
        tx = p.x + 34;
      }
      g += `<text class="lbl" x="${tx}" y="${p.y + 18}">${esc(n.label)}</text>`;
      if (occ(n.card).mand) g += `<circle class="mand-dot" cx="${p.x + p.w - 6}" cy="${p.y + 6}" r="3"><title>${esc(S.mand)}</title></circle>`;
      g += '</g>';
      if (n.children && n.children.length) {
        const tx2 = p.dir > 0 ? p.x + p.w + 8 : p.x - 8, closed = !!mmCollapsed[n.uid];
        g += `<g class="mm-tog" data-tog="${esc(n.uid)}" role="button" tabindex="0" aria-expanded="${!closed}" aria-label="${esc(n.label)}"><circle cx="${tx2}" cy="${p.cy}" r="7"/><text x="${tx2}" y="${p.cy + 4}" text-anchor="middle">${closed ? '+' : '−'}</text></g>`;
      }
      return g;
    };
    nodes += nodeSvg(TREE, pos.get(TREE));
    all.forEach(it => { nodes += nodeSvg(it.n, pos.get(it.n)); });

    box.style.height = Math.ceil(Ht * mmZoom) + 4 + 'px';
    box.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="${W * mmZoom}" height="${Ht * mmZoom}" viewBox="0 0 ${W} ${Ht}" role="group" aria-label="${esc(TREE.label)}" style="font-family:${esc(fam)}">${edges}${nodes}</svg>`;
    const svg = box.querySelector('svg');
    const act = e => {
      const t = e.target.closest('[data-tog]');
      if (t) {
        const id = t.dataset.tog;
        if (mmCollapsed[id]) delete mmCollapsed[id]; else mmCollapsed[id] = true;
        drawMindmap(box, detail);
        const again = [...box.querySelectorAll('[data-tog]')].find(x => x.dataset.tog === id);
        if (again) again.focus();
        return;
      }
      const g = e.target.closest('.mm-node[data-uid]');
      if (!g) return;
      mmSel = g.dataset.uid;
      drawMindmap(box, detail);
      showDetail(detail, findNode(mmSel));
      const again = [...box.querySelectorAll('.mm-node[data-uid]')].find(x => x.dataset.uid === mmSel);
      if (again) again.focus();
    };
    svg.addEventListener('click', act);
    svg.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); act(e); } });
    return { W, H: Ht };
  }

  function valueListHtml(f, vl) {
    const hit = exampleConcept(f);
    const head = `<div class="vl-head">${vl.link ? `<a href="${url(vl.link)}"${ext(vl.link)}>${esc(vl.title)}</a>` : `<span>${esc(vl.title)}</span>`}<span>${count(vl)} ${esc(S.codes)}</span></div>`;
    const body = vl.concepts.length
      ? '<ol>' + vl.concepts.map(c => {
        const other = LANG !== 'en' && c.en && c.en !== concept(c) ? ' · ' + esc(c.en) : '';
        return `<li${c === hit ? ` class="hit" data-hit="${esc(S.exampleHit)}"` : ''}><span>${esc(concept(c))}</span><span class="mono">${esc(c.code)}${other}</span></li>`;
      }).join('') + '</ol>'
      : `<div class="vl-note">${count(vl)}${esc(S.tooMany)}</div>`;
    const inc = vl.incomplete && vl.incomplete.length ? `<div class="vl-note">${esc(S.notExpanded + vl.incomplete.join(', '))}</div>` : '';
    return `<div class="vl">${head}${body}${inc}</div>`;
  }
  function showDetail(el, n) {
    if (!n) return;
    const p = [];
    if (n.f) {
      const f = n.f, vl = list(f);
      if (altLabel(f)) p.push(`<p class="alt">${esc(altLabel(f))}</p>`);
      if (f.note) p.push(`<p>${esc(f.note)}</p>`);
      if (f.code) p.push(`<p class="muted">${esc(S.itemCode)}${codeHtml(f.code)}</p>`);
      const bl = bindingLine(f);
      if (bl) p.push(`<p class="muted">${bl}</p>`);
      if (f.type === 'reference' && f.targets) p.push(`<p class="muted">${esc(S.refersTo + f.targets.join(', '))}</p>`);
      if (f.type === 'coded' && !vl && !f.code && !f.binding) p.push(`<p class="muted">${esc(S.noList)}</p>`);
      if (f.example) p.push(`<p class="muted">${esc(S.exampleV)}<b class="exv">${esc(f.example)}</b></p>`);
      if (f.resource) p.push(`<p class="muted">${esc(S.resource)}${f.resourceLink ? `<a href="${url(f.resourceLink)}"${ext(f.resourceLink)}>${esc(f.resource)}</a>` : esc(f.resource)}</p>`);
      p.push(`<p class="muted mono">${esc(f.path)}</p>`);
      if (vl && vl.concepts.length) p.push(valueListHtml(f, vl));
    } else {
      groupDesc(n).forEach(b => p.push(`<p class="muted">${b}</p>`));
      p.push(`<p class="muted">${esc(S.elements(n.children.length))}${n.children.map(c => esc(c.label)).join(', ')}</p>`);
      if (n.sec && n.sec.slice) p.push(`<p class="muted mono">Composition.section:${esc(n.sec.slice)}${n.sub ? '.section:' + esc(n.sub.slice) : ''}</p>`);
    }
    el.innerHTML = `<div class="hd">${icon(n.type)} ${esc(n.label)} ${tags(n)}</div>${p.join('')}`;
  }

  /* ---------------------------------------------------------------- form preview */

  let formClosed = {};
  function control(f, fill) {
    const id = 'fx-f-' + f.id, ex = fill ? f.example : '', aria = ` aria-label="${esc(label(f))}"`, vl = list(f);
    const iso = /^\d{4}-\d\d-\d\d/.test(ex);
    const rest = iso && ex.length > 10 && !/^\d{4}-\d\d-\d\dT\d\d:\d\d/.test(ex) ? `<span class="note">${esc(ex)}</span>` : '';
    switch (f.type) {
      case 'coded':
        if (vl && vl.concepts.length) {
          const hit = fill ? exampleConcept(f) : null;
          return `<select id="${id}"${aria}><option value="">-</option>` + vl.concepts.map(c =>
            `<option value="${esc(c.code)}"${c === hit ? ' selected' : ''}>${esc(concept(c))}</option>`).join('') + '</select>' +
            (fill && !hit && ex ? `<span class="note">${esc(ex)}</span>` : '');
        }
        return `<input type="text" id="${id}"${aria} value="${esc(ex)}" placeholder="${esc(f.code ? f.code.system + ' ' + f.code.code : (vl ? vl.title : (f.binding ? f.binding.title : '')))}">`;
      case 'boolean':
        return `<input type="checkbox" id="${id}"${aria}${fill && /^(true|yes|ha|да)/i.test(ex) ? ' checked' : ''}>`;
      case 'date':
        return iso || !fill ? `<input type="date" id="${id}"${aria} value="${esc(ex.slice(0, 10))}">${rest}` : `<input type="text" id="${id}"${aria} value="${esc(ex)}">`;
      case 'datetime':
        if (iso && (ex.length < 11 || rest)) return `<input type="date" id="${id}"${aria} value="${esc(ex.slice(0, 10))}">${rest}`;
        return iso || !fill ? `<input type="datetime-local" id="${id}"${aria} value="${esc(ex.slice(0, 16))}">` : `<input type="text" id="${id}"${aria} value="${esc(ex)}">`;
      case 'period':
        return `<input type="date" id="${id}"${aria}><span class="sep">-</span><input type="date"${aria}>${ex ? `<span class="note">${esc(ex)}</span>` : ''}`;
      case 'quantity':
      case 'count': {
        const parts = f.example.split(' '), num = /^-?\d+([.,]\d+)?$/.test(parts[0]);
        if (!num && fill && ex) return `<input type="text" id="${id}"${aria} value="${esc(ex)}">`;
        return `<input type="number" class="num" step="any" id="${id}"${aria} value="${fill && num ? esc(parts[0].replace(',', '.')) : ''}">` +
          (num && parts.length > 1 ? `<input type="text" class="unit" value="${esc(parts.slice(1).join(' '))}" aria-label="${esc(label(f) + ' - ' + S.unit)}">` : '');
      }
      case 'reference':
        return `<span class="refbox" id="${id}">${icon('reference')} ${esc(fill && ex ? ex : (f.targets || [f.resource]).join(' | '))}</span>`;
      case 'none':
        return `<span class="note">${esc(S.notSent)}</span>`;
      case 'derived':
        return `<span class="note">${esc(S.derivedNote)}</span>${ex ? ` <span class="note">${esc(ex)}</span>` : ''}`;
      case 'attachment':
        return `<span class="refbox">${icon('attachment')} ${esc(S.types.attachment)}</span>${ex ? ` <span class="note">${esc(ex)}</span>` : ''}`;
      default:
        return `<input type="text" id="${id}"${aria} value="${esc(ex)}">`;
    }
  }
  function formNode(n, d) {
    if (n.children) {
      const closed = formClosed[n.uid] ?? (d === 1 && FIELDS.length > 90 && TREE.children.indexOf(n) > 1);
      const opt = n.card && !occ(n.card).mand ? ' opt' : '';
      return `<div class="fs d${d > 1 ? 1 : 0}${opt}${closed ? ' closed' : ''}" data-fs="${esc(n.uid)}">
        <button type="button" class="fh" aria-expanded="${!closed}"><span class="tw">▾</span>${icon('group')} ${esc(n.label)} ${n.card ? `<span class="car">[${esc(n.card)}]</span>` : ''}</button>
        <div class="fb">${n.sec && L(n.sec.intro) ? `<div class="note">${esc(L(n.sec.intro))}</div>` : ''}${n.children.map(c => formNode(c, d + 1)).join('')}</div></div>`;
    }
    const f = n.f, o = occ(n.card);
    const lab = `<label class="fl" for="fx-f-${esc(f.id)}">${icon(n.type)} ${esc(n.label)}${o.mand ? ` <span class="req" title="${esc(S.mand)}">*</span>` : ''}${n.card ? ` <span class="car">[${esc(n.card)}]</span>` : ''}</label>`;
    return `<div class="fr">${lab}<div class="fc"><div class="fv">${control(f, state.example)}</div>${state.paths ? `<div class="path">${esc(f.path)}</div>` : ''}</div></div>`;
  }
  function renderForm(pane) {
    pane.innerHTML = `<div class="toolbar">
        <button type="button" class="tbtn" id="fx-ex">${esc(state.example ? S.clearExample : S.fillExample)}</button>
        <label><input type="checkbox" id="fx-paths" ${state.paths ? 'checked' : ''}> ${esc(S.showPaths)}</label>
        <span class="sp"></span><span><span class="req">*</span> ${esc(S.formLegend)}</span></div>
      <div class="form">${TREE.children.map(c => formNode(c, 1)).join('')}</div>`;
    pane.querySelector('#fx-ex').onclick = () => { state.example = !state.example; renderForm(pane); pane.querySelector('#fx-ex').focus(); };
    pane.querySelector('#fx-paths').onchange = e => { state.paths = e.target.checked; save(); renderForm(pane); pane.querySelector('#fx-paths').focus(); };
    pane.querySelector('.form').addEventListener('click', e => {
      const h = e.target.closest('.fh');
      if (!h) return;
      const fs = h.parentElement, closed = fs.classList.toggle('closed');
      formClosed[fs.dataset.fs] = closed;
      h.setAttribute('aria-expanded', String(!closed));
    });
  }

  /* ---------------------------------------------------------------- loading */

  function writeUrl() {
    const u = new URL(location.href);
    u.searchParams.set('form', state.form);
    u.hash = state.view === 'overview' ? '' : state.view;
    history.replaceState(null, '', u.pathname + u.search + u.hash);
  }
  function go(form) {
    state.form = form;
    $('#fx-form').value = form;
    fetch('form-explorer/form-' + encodeURIComponent(form) + '.json').then(r => {
      if (!r.ok) throw new Error(r.status + ' ' + r.statusText);
      return r.json();
    }).then(data => {
      if (form !== state.form) return;
      M = data;
      FIELDS = [];
      M.sections.forEach(s => s.fields.forEach(f => FIELDS.push(f)));
      TREE = buildTree();
      mmCollapsed = {};
      mmZoom = null;
      mmSel = null;
      formClosed = {};
      if (FIELDS.length > 90) TREE.children.forEach(c => { mmCollapsed[c.uid] = true; });
      render();
    }).catch(e => {
      if (form !== state.form) return;
      const err = `<p class="status err">${esc(S.failed + e.message)}</p>`;
      if (!M) { $('#fx-pane').innerHTML = err; return; }
      state.form = M.form;
      $('#fx-form').value = M.form;
      writeUrl();
      const t = $('#fx-title'), old = t.querySelector('.status.err');
      if (old) old.remove();
      t.insertAdjacentHTML('afterbegin', err);
    });
  }

  root.innerHTML = `<p class="status">${esc(S.loading)}</p>`;
  fetch('form-explorer/index.json').then(r => {
    if (!r.ok) throw new Error(r.status + ' ' + r.statusText);
    return r.json();
  }).then(index => {
    shell(index);
    const q = new URLSearchParams(location.search).get('form');
    const h = location.hash.slice(1);
    state.view = VIEWS.includes(h) ? h : 'overview';
    go(index.some(x => x.form === q) ? q : index[0].form);
  }).catch(e => {
    root.innerHTML = `<p class="status err">${esc(S.failed + e.message)}</p>`;
  });
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { if (M && state.view === 'mindmap') render(); });
})();
